    id,
    name: offer.name,
    role: offer.role,
    max: offer.max,
    hp: offer.max,
    damage: isCaster(offer) ? founderRoles[offer.role].damage : 6,
    level: 1,
    xp: 0,
    points: 0,
    injury: false,
    dead: false,
    fatigue: 0,
    resolve: 65,
    traits: [...offer.traits],
    race: offer.race || "human",
    personalQuest: { stage: 0, outcome: null },
    spellSpent: { 1: 0, 2: 0 },
    armor: 0,
    weapon: 0,
    profession: offer.profession,
    professionXP: 0,
    professionXPBy: {},
    talent: null,
    advancedSkill: null,
