    s.event ||
    !s.campOpen ||
    !p ||
    p.dead ||
    p.hp <= 0 ||
    !isCaster(p) ||
    s.realm.shards < 1 ||
    !(p.spellSpent?.[1] || p.spellSpent?.[2])
