  pixel(c, 10, 5, 8, 8, skin);
  pixel(c, 16, 8, 2, 5, "#b18a64");
  pixel(c, 11, 9, 1, 1, "#353b32");
  pixel(c, 16, 9, 1, 1, "#353b32");
  pixel(c, 13, 12, 3, 1, "#8d654d");
