    pixel(c, 9, 2, 9, 2, "#7c8554");
    for (let i = 0; i < 7; i++) pixel(c, 10 + i, 15 + i, 2, 2, "#b39461");
    pixel(c, 23, 12, 1, 3, "#c49f61");
    pixel(c, 24, 15, 1, 8, "#a6814f");
    pixel(c, 23, 23, 1, 3, "#c49f61");
    pixel(c, 22, 14, 1, 11, "#ded1a7");
